            "heading": "4-sla-aware--sla--latencyerrorcost-slo-compliance",
            "content": "When `hardConstraints: true`, candidates are sorted primarily by **violation score**\r\n(how far they exceed any SLO), then by composite score. Otherwise it's just\r\nthe composite score."
